/* ===== Terminale ES · Thème 1 · 1.3 Le climat du futur · Activité 2 « Comment sont faits les modèles climatiques ? » : contenus, d'après la fiche et le corrigé du professeur ===== */
const PROBLEM = "Comment sont construits les modèles climatiques, comment les évalue-t-on et que nous apprennent-ils ?";
const gap = `<span class="gap">………</span>`;
const LZS = lzSplit(), NAT = ATT.nat(), ALL = ATT.all(), NAT15 = decMean(NAT.st.mean, 2015), ALL15 = decMean(ALL.st.mean, 2015);
const PAL3 = paleo(3)[50], D0 = ebm(0);
const SSPM = k => { const E = ens({ sol: 1, vol: 1, ghg: 1, aer: 1 }, k), r = E.runs.map(s => s.slice(2081 - 1850, 2101 - 1850).reduce((a, b) => a + b, 0) / 20); return r.reduce((a, b) => a + b, 0) / r.length; };
const P1 = SSPM("1-2.6"), P5 = SSPM("5-8.5");

/* les trois phrases du corrigé (une par partie) et le paragraphe synthétique */
const PSYN = ["Les modèles climatiques sont des programmes informatiques qui traduisent les lois de la physique et de la chimie en équations. Ils couplent plusieurs composantes du système climatique : atmosphère, océans, continents, glaces de mer, ainsi que des rétroactions climatiques.",
  "Les modèles sont évalués en comparant leurs résultats aux observations actuelles (par exemple les données satellites) et aux climats passés connus grâce aux indices géologiques. Quand il existe des écarts, les chercheurs modifient le modèle pour l'améliorer.",
  "Les modèles permettent de tester différents scénarios climatiques. Ils montrent que l'augmentation récente de la température globale est correctement reproduite seulement lorsque les émissions anthropiques de gaz à effet de serre sont prises en compte."];
const PFAUX = [["Les modèles climatiques prévoient le temps qu'il fera chaque jour jusqu'en 2100, grâce à des thermomètres très précis répartis sur la Terre.", "Les modèles climatiques sont des maquettes de la Terre construites en laboratoire avec de l'eau, de la glace et une lampe."],
  ["Un modèle est jugé fiable dès qu'il tourne sur un supercalculateur : il n'a pas besoin d'être comparé à la réalité.", "Les modèles sont évalués en attendant l'année 2100 pour vérifier si leurs prévisions étaient justes."],
  ["Les modèles montrent que le réchauffement récent s'explique entièrement par l'activité du Soleil et des volcans.", "Les modèles montrent que l'on ne peut rien dire du réchauffement récent, car chaque modèle donne un résultat différent."]];
const SYNTH = ["Les modèles climatiques sont des programmes informatiques qui simulent le climat à long terme à partir d'équations issues des lois physiques et chimiques.", "Ils prennent en compte plusieurs composantes du système climatique, comme l'atmosphère, les océans, les continents, les glaces et les rétroactions.", "Pour vérifier leur fiabilité, les scientifiques comparent les résultats des modèles aux observations actuelles et aux climats passés.", "Si des écarts apparaissent, les modèles sont corrigés et améliorés.", "Enfin, ils permettent de tester différents scénarios et montrent que le réchauffement récent n'est bien expliqué que si l'on tient compte des émissions humaines de gaz à effet de serre."];
const SYN_A = ["Les modèles climatiques sont des programmes informatiques qui…", "Ils prennent en compte…", "Pour vérifier leur fiabilité,…", "Si des écarts apparaissent,…", "Enfin, ils permettent…"];
const SYN_B = ["simulent le climat à long terme à partir d'équations issues des lois physiques et chimiques.", "plusieurs composantes du système climatique, comme l'atmosphère, les océans, les continents, les glaces et les rétroactions.", "les scientifiques comparent les résultats des modèles aux observations actuelles et aux climats passés.", "les modèles sont corrigés et améliorés.", "de tester différents scénarios et montrent que le réchauffement récent n'est bien expliqué que si l'on tient compte des émissions humaines de gaz à effet de serre."];
const PARAIT = ["a3", "b2", "c2"];
function paraParts() {
  return PARAIT.map(id => { const st = IT()[id], it = ITEMS[id].it; if (!st || !st.v) return ""; const k = it.parts.findIndex(p => p.para); if (k < 0) return ""; const v = st.v[k], p = it.parts[k]; if (p.t === "redac") return String(v || "").trim(); return v === undefined || v === null ? "" : p.o[v]; });
}
function myPara() { const st = IT().d1; if (!st || !st.v) return ""; const it = ITEMS.d1.it, k = it.parts.findIndex(p => p.t === "redac"); if (k >= 0) return String(st.v[k] || "").trim(); const m = st.v[0] || {}; if (SYN_A.some((_, i) => m[i] === undefined)) return ""; return SYN_A.map((a, i) => a.replace(/…$/, "") + " " + SYN_B[m[i]]).join(" "); }

const HOME = { slug: "comment-sont-faits-les-modeles", short: "Comment sont faits les modèles climatiques", last: "d1", lastG: "p4", lastK: 0, dur: "environ 1 h 15, en une ou deux séances",
  kicker: "Thème 1 · Chapitre 3 · Le climat du futur · Activité 2", title: "Le laboratoire du climatologue",
  intro: "Tu entres dans un laboratoire de modélisation du climat. Tu vas construire une Terre virtuelle module par module, la découper en mailles, comprendre pourquoi on prévoit le climat mais pas la météo de 2100, régler un vrai petit modèle sur le climat actuel, le tester sur la dernière glaciation, puis faire tourner 12 modèles pour savoir d'où vient le réchauffement et ce qui nous attend.",
  lab: "Le problème", goal: "Objectif : rédiger, partie après partie, un paragraphe synthétique qui explique comment sont construits les modèles climatiques, comment on les évalue et on les améliore, et ce qu'ils nous apportent.",
  fact: "Le prix Nobel de physique 2021 a récompensé Syukuro Manabe et Klaus Hasselmann pour la modélisation physique du climat de la Terre, et Giorgio Parisi pour ses travaux sur le désordre dans les systèmes complexes. Le premier calcul du temps sur ordinateur, lui, date de 1950 : il a fallu 24 heures de calcul pour une prévision… à 24 heures.",
  parts: "Les quatre parties de l'activité", recop: "Bilan à recopier dans le cahier",
  txt: "ACTIVITÉ 2 · COMMENT SONT FAITS LES MODÈLES CLIMATIQUES ?\nTerminale · Enseignement scientifique · Thème 1 · Chapitre 3 : le climat du futur",
  comps: { mod: "Utiliser un logiciel de simulation", lire: "Analyser des données, lire un graphique", calc: "Calculer, estimer un ordre de grandeur", conn: "Mobiliser ses connaissances", crit: "Critiquer un modèle", rais: "Pratiquer des langages, argumenter" },
  vers: { g: { icon: "🧭", short: "Guidée", name: "Version guidée", q: "guidee", desc: "Je réponds par des choix et des valeurs lues, puis je choisis les phrases de mon paragraphe et je l'assemble." },
    l: { icon: "🎓", short: "Exigeante", name: "Version exigeante", q: "exigeante", desc: "Les mêmes laboratoires, plus de calculs, et je rédige moi-même mon paragraphe synthétique, partie après partie." } },
  extraTitle: "Mon paragraphe synthétique",
  extra: () => { const P = paraParts(), F = myPara(); return `MON PARAGRAPHE SYNTHÉTIQUE\n${P.map((t, i) => `Partie ${i + 1} : ${t || "—"}`).join("\n")}\nVersion finale : ${F || "—"}\n`; },
  extraHTML: () => { const F = myPara(), P = paraParts(); return F ? `<p class="mypara">${esc(F)}</p>` : `<ol class="paral">${P.map((t, i) => `<li><span class="kicker">Partie ${i + 1}</span><p>${t ? esc(t) : "—"}</p></li>`).join("")}</ol><p class="lead">Ta version finale apparaîtra ici après la partie 4.</p>`; } };

const WG = (title, w, sim) => ({ title, w, sim });
const DOC1 = { title: "Document 1 · Qu'est-ce qu'un modèle numérique du climat ?", html: `<p>${nb("Un modèle numérique du climat est un programme informatique qui fabrique une Terre virtuelle : il doit y reproduire les mêmes phénomènes que sur la vraie Terre. Pour cela, on écrit sous forme d'équations mathématiques les lois physiques de l'atmosphère et de l'océan, mais aussi le comportement de la végétation et des sols. Ces équations sont ensuite résolues par des supercalculateurs.")}</p><p>${nb("Le premier modèle de l'atmosphère date de 1950. Il en existe aujourd'hui plus de vingt. Le GIEC utilise des modèles qui couplent l'atmosphère, l'océan, les glaces de mer et les continents (MCGOA : modèles de circulation générale océan-atmosphère). On les complète par des rétroactions, notamment celles du cycle du carbone : ce sont les modèles du système Terre (MST).")}</p><p class="cap">D'après Jean-Louis Dufresne (Laboratoire de météorologie dynamique) et un manuel de Terminale.</p>` };
const DOC2 = { title: "Document 2 · La taille des mailles des modèles du GIEC", html: tbl(["Rapport du GIEC", "Taille des mailles (modèles mondiaux)"], [["1990 (1er rapport)", "≈ 500 km"], ["1995", "≈ 250 km"], ["2001", "≈ 180 km"], ["2007", "≈ 110 km"], ["Aujourd'hui", "≈ 100 km (modèles régionaux : 10 à 25 km)"]]) + `<p class="cap">${nb("D'après le GIEC (4e rapport, 2007, chapitre 1). Surface de la Terre : 510 millions de km². Surface du Luxembourg : 2 586 km².")}</p>` };
const DOC3 = { title: "Document 3 · Prévision météo ou projection climatique ?", html: `<p>${nb("Les modèles météorologiques et les modèles climatiques utilisent des équations comparables. Mais la météo cherche à prévoir l'état de l'atmosphère à une date précise, quelques jours à l'avance. Les projections climatiques ne cherchent pas à dire le temps qu'il fera tel jour dans cent ans : elles calculent le climat, c'est-à-dire les statistiques du temps (moyennes, variabilité, extrêmes) sur plusieurs décennies.")}</p>` };
const DOC4 = { title: "Document 4 · Évaluer un modèle sur le climat actuel", html: `<p>${nb("Pour évaluer un modèle, on compare ses résultats aux observations actuelles : stations météorologiques, bouées océaniques et surtout satellites (températures, nuages en trois dimensions…). Si l'écart entre les valeurs simulées et mesurées est important, les chercheurs font évoluer le modèle pour le réduire. Ces comparaisons permettent aussi de vérifier que le modèle rend compte des perturbations dues aux activités humaines, comme la déforestation.")}</p>` };
const DOC5 = { title: "Document 5 · Évaluer un modèle sur un climat passé", html: `<div class="loop5"><span><b>Paramètres d'entrée</b> connus d'après les calculs et les indices géologiques : orbite de la Terre et composition de l'atmosphère il y a 21 000 ans</span><span aria-hidden="true">→</span><span><b>Calculs</b> par le modèle</span><span aria-hidden="true">→</span><span><b>Résultats en sortie</b> : température et extension des calottes glaciaires</span><span aria-hidden="true">→</span><span><b>Comparaison</b> avec les données géologiques (moraines, sédiments, glaces)</span><span aria-hidden="true">↺</span><span>Si différences : <b>modification du modèle</b></span></div><p>${nb("Il y a 21 000 ans, au dernier maximum glaciaire, d'immenses calottes recouvraient le nord de l'Amérique et de l'Europe. Les indices géologiques indiquent un climat mondial environ 6 °C plus froid qu'avant l'ère industrielle (entre 5 et 7 °C, d'après le GIEC).")}</p>` };
const DOC6 = { title: "Document 6 · Simuler le passé récent, avec ou sans les activités humaines", html: `<p>${nb("Les chercheurs font tourner plus d'une dizaine de modèles de 1850 à aujourd'hui. Ils leur donnent les facteurs naturels qui modifient le bilan radiatif de la Terre (activité du Soleil, éruptions volcaniques), avec ou sans les facteurs humains (gaz à effet de serre, aérosols de pollution, qui refroidissent). Puis ils comparent les températures simulées aux températures observées.")}</p>` };
const DOC7 = { title: "Document 7 · Les scénarios du GIEC (rapport 2021)", html: tbl(["Scénario", "Hypothèse sur les émissions", "Réchauffement en 2081-2100 (par rapport à 1850-1900)"], [["SSP1-2.6", "fortes baisses, neutralité carbone dans la seconde moitié du siècle", "1,8 °C (1,3 à 2,4)"], ["SSP2-4.5", "émissions proches d'aujourd'hui jusqu'en 2050, puis baisse", "2,7 °C (2,1 à 3,5)"], ["SSP5-8.5", "émissions qui doublent d'ici 2050", "4,4 °C (3,3 à 5,7)"]]) + `<p class="cap">${nb("Meilleure estimation et fourchette très probable : GIEC, 6e rapport, groupe 1 (2021).")}</p>` };

const BIL = [
  "Un <u>modèle climatique</u> est un programme informatique qui traduit les <u>lois de la physique et de la chimie</u> en équations, puis les <u>résout numériquement</u> sur des supercalculateurs.",
  "Il <u>couple</u> plusieurs composantes du système climatique : atmosphère, océans, continents et glaces de mer (<u>MCGOA</u>), auxquels on ajoute les <u>rétroactions</u>, notamment du cycle du carbone (<u>MST</u>).",
  "La Terre est découpée en <u>mailles</u> (≈ 100 km aujourd'hui) : diviser la maille par 2, c'est environ <u>8 fois plus de calculs</u>. Un modèle ne prévoit pas la météo d'un jour précis : il calcule le <u>climat</u>, c'est-à-dire les statistiques du temps sur plusieurs décennies.",
  "On <u>évalue</u> un modèle en comparant ses résultats aux <u>observations actuelles</u> (stations, bouées, satellites) et aux <u>climats passés</u> connus grâce aux indices géologiques (−21 000 ans : environ −6 °C). S'il y a des écarts, on <u>modifie le modèle</u> pour l'améliorer.",
  `Les modèles permettent de <u>tester des scénarios</u>. Sans les émissions humaines, ils ne reproduisent pas le réchauffement récent (≈ ${f1(NAT15)} °C au lieu de 1,1 °C en 2011-2020) : il n'est expliqué que si l'on tient compte des <u>émissions anthropiques de gaz à effet de serre</u>.`,
  "Nombreux et indépendants, les modèles donnent une <u>fourchette</u> pour chaque scénario : de 1,8 °C (SSP1-2.6) à 4,4 °C (SSP5-8.5) de réchauffement à la fin du siècle, selon nos choix d'émissions."];
const bilanHTML = () => BIL.map(x => `<p>${nb(x)}</p>`).join("");
